window.TXB=window.TXB||{};TXB["svd/Mar"]={"1:1":"بدء إنجيل يسوع المسيح ابن الله:","1:2":"كما هو مكتوب في الأنبياء: «ها أنا أرسل أمام وجهك ملاكي, الذي يهيئ طريقك قدامك.","1:3":"صوت صارخ في البرية: أعدوا طريق الرب, اصنعوا سبله مستقيمة».","1:4":"كان يوحنا يعمد في البرية ويكرز بمعمودية التوبة لمغفرة الخطايا.","1:5":"وخرج إليه جميع كورة اليهودية وأهل أورشليم واعتمدوا جميعهم منه في نهر الأردن, معترفين بخطاياهم.","1:6":"وكان يوحنا يلبس وبر الإبل, ومنطقة من جلد على حقويه, ويأكل جرادا وعسلا بريا.","1:7":"وكان يكرز قائلا: «يأتي بعدي من هو أقوى مني, الذي لست أهلا أن أنحني وأحل سيور حذائه.","1:8":"أنا عمدتكم بالماء, وأما هو فسيعمدكم بالروح القدس».","1:9":"وفي تلك الأيام جاء يسوع من ناصرة الجليل واعتمد من يوحنا في الأردن.","1:10":"وللوقت وهو صاعد من الماء رأى السماوات قد انشقت, والروح مثل حمامة نازلا عليه.","1:11":"وكان صوت من السماوات: «أنت ابني الحبيب الذي به سررت!».","1:12":"وللوقت أخرجه الروح إلى البرية","1:13":"وكان هناك في البرية أربعين يوما يجرب من الشيطان. وكان مع الوحوش. وصارت الملائكة تخدمه.","1:14":"وبعدما أسلم يوحنا جاء يسوع إلى الجليل يكرز ببشارة ملكوت الله","1:15":"ويقول: «قد كمل الزمان واقترب ملكوت الله, فتوبوا وآمنوا بالإنجيل».","1:16":"وفيما هو يمشي عند بحر الجليل أبصر سمعان وأندراوس أخاه يلقيان شبكة في البحر, فإنهما كانا صيادين.","1:17":"فقال لهما يسوع: «هلم ورائي فأجعلكما تصيران صيادي الناس».","1:18":"فللوقت تركا شباكهما وتبعاه.","1:19":"ثم اجتاز من هناك قليلا فرأى يعقوب بن زبدي ويوحنا أخاه, وهما في السفينة يصلحان الشباك.","1:20":"فدعاهما للوقت. فتركا أباهما زبدي في السفينة مع الأجرى وذهبا وراءه.","1:21":"ثم دخلوا كفرناحوم, وللوقت دخل المجمع في السبت وصار يعلم.","1:22":"فبهتوا من تعليمه لأنه كان يعلمهم كمن له سلطان وليس كالكتبة.","1:23":"وكان في مجمعهم رجل به روح نجس, فصرخ","1:24":"قائلا: «آه! ما لنا ولك يا يسوع الناصري! أتيت لتهلكنا! أنا أعرفك من أنت قدوس الله!»","1:25":"فانتهره يسوع قائلا: «اخرس واخرج منه!»","1:26":"فصرعه الروح النجس وصاح بصوت عظيم وخرج منه.","1:27":"فتحيروا كلهم, حتى سأل بعضهم بعضا قائلين: «ما هذا؟ ما هو هذا التعليم الجديد؟ لأنه بسلطان يأمر حتى الأرواح النجسة فتطيعه!»","1:28":"فخرج خبره للوقت في كل الكورة المحيطة بالجليل.","1:29":"ولما خرجوا من المجمع جاءوا للوقت إلى بيت سمعان وأندراوس مع يعقوب ويوحنا","1:30":"وكانت حماة سمعان مضطجعة محمومة, فللوقت أخبروه عنها.","1:31":"فتقدم وأقامها ماسكا بيدها, فتركتها الحمى حالا وصارت تخدمهم.","1:32":"ولما صار المساء, إذ غربت الشمس, قدموا إليه جميع السقماء والمجانين.","1:33":"وكانت المدينة كلها مجتمعة على الباب.","1:34":"فشفى كثيرين كانوا مرضى بأمراض مختلفة, وأخرج شياطين كثيرة, ولم يدع الشياطين يتكلمون لأنهم عرفوه.","1:35":"وفي الصبح باكرا جدا قام وخرج ومضى إلى موضع خلاء, وكان يصلي هناك","1:36":"فتبعه سمعان والذين معه.","1:37":"ولما وجدوه قالوا له: «إن الجميع يطلبونك».","1:38":"فقال لهم: «لنذهب إلى القرى المجاورة لأكرز هناك أيضا, لأني لهذا خرجت».","1:39":"فكان يكرز في مجامعهم في كل الجليل ويخرج الشياطين.","1:40":"فأتى إليه أبرص يطلب إليه جاثيا وقائلا له: «إن أردت تقدر أن تطهرني!»","1:41":"فتحنن يسوع ومد يده ولمسه وقال له: «أريد, فاطهر».","1:42":"فللوقت وهو يتكلم ذهب عنه البرص وطهر.","1:43":"فانتهره وأرسله للوقت","1:44":"وقال له: «انظر, لا تقل لأحد شيئا, بل اذهب أر نفسك للكاهن وقدم عن تطهيرك ما أمر به موسى, شهادة لهم».","1:45":"وأما هو فخرج وابتدأ ينادي كثيرا ويذيع الخبر, حتى لم يعد يقدر أن يدخل مدينة ظاهرا, بل كان خارجا في مواضع خالية, وكانوا يأتون إليه من كل ناحية.","2:1":"ثم دخل كفرناحوم أيضا بعد أيام, فسمع أنه في بيت.","2:2":"وللوقت اجتمع كثيرون حتى لم يعد يسع ولا ما حول الباب. فكان يخاطبهم بالكلمة.","2:3":"وجاءوا إليه مقدمين مفلوجا يحمله أربعة.","2:4":"وإذ لم يقدروا أن يقتربوا إليه من أجل الجمع, كشفوا السقف حيث كان. وبعد ما نقبوه دلوا السرير الذي كان المفلوج مضطجعا عليه.","2:5":"فلما رأى يسوع إيمانهم, قال للمفلوج: «يا بني, مغفورة لك خطاياك».","2:6":"وكان قوم من الكتبة هناك جالسين يفكرون في قلوبهم:","2:7":"«لماذا يتكلم هذا هكذا بتجاديف؟ من يقدر أن يغفر خطايا إلا الله وحده؟»","2:8":"فللوقت شعر يسوع بروحه أنهم يفكرون هكذا في أنفسهم, فقال لهم: «لماذا تفكرون بهذا في قلوبكم؟","2:9":"أيما أيسر: أن يقال للمفلوج مغفورة لك خطاياك, أم أن يقال: قم واحمل سريرك وامش؟","2:10":"ولكن لكي تعلموا أن لابن الإنسان سلطانا على الأرض أن يغفر الخطايا» - قال للمفلوج:","2:11":"«لك أقول قم واحمل سريرك واذهب إلى بيتك».","2:12":"فقام للوقت وحمل السرير وخرج قدام الكل, حتى بهت الجميع ومجدوا الله قائلين: «ما رأينا مثل هذا قط!».","2:13":"ثم خرج أيضا إلى البحر وأتى إليه كل الجمع فعلمهم.","2:14":"وفيما هو مجتاز رأى لاوي بن حلفى جالسا عند مكان الجباية, فقال له: «اتبعني». فقام وتبعه.","2:15":"وفيما هو متكئ في بيته كان كثيرون من العشارين والخطاة يتكئون مع يسوع وتلاميذه, لأنهم كانوا كثيرين وتبعوه.","2:16":"وأما الكتبة والفريسيون فلما رأوه يأكل مع العشارين والخطاة, قالوا لتلاميذه: «ما باله يأكل ويشرب مع العشارين والخطاة؟»","2:17":"فلما سمع يسوع قال لهم: «لا يحتاج الأصحاء إلى طبيب بل المرضى. لم آت لأدعو أبرارا بل خطاة إلى التوبة».","2:18":"وكان تلاميذ يوحنا والفريسيين يصومون, فجاءوا وقالوا له: «لماذا يصوم تلاميذ يوحنا والفريسيين, وأما تلاميذك فلا يصومون؟»","2:19":"فقال لهم يسوع: «هل يستطيع بنو العرس أن يصوموا والعريس معهم؟ ما دام العريس معهم لا يستطيعون أن يصوموا.","2:20":"ولكن ستأتي أيام حين يرفع العريس عنهم, فحينئذ يصومون في تلك الأيام.","2:21":"ليس أحد يخيط رقعة من قطعة جديدة على ثوب عتيق, وإلا فالملء الجديد يأخذ من العتيق فيصير الخرق أردأ.","2:22":"وليس أحد يجعل خمرا جديدة في زقاق عتيقة, لئلا تشق الخمر الجديدة الزقاق, فالخمر تنصب والزقاق تتلف. بل يجعلون خمرا جديدة في زقاق جديدة».","2:23":"واجتاز في السبت بين الزروع, فابتدأ تلاميذه يقطفون السنابل وهم سائرون.","2:24":"فقال له الفريسيون: «انظر. لماذا يفعلون في السبت ما لا يحل؟»","2:25":"فقال لهم: «أما قرأتم قط ما فعله داود حين احتاج وجاع هو والذين معه","2:26":"كيف دخل بيت الله في أيام أبيأثار رئيس الكهنة, وأكل خبز التقدمة الذي لا يحل أكله إلا للكهنة, وأعطى الذين كانوا معه أيضا؟»","2:27":"ثم قال لهم: «السبت إنما جعل لأجل الإنسان, لا الإنسان لأجل السبت.","2:28":"إذا ابن الإنسان هو رب السبت أيضا».","3:1":"ثم دخل أيضا إلى المجمع, وكان هناك رجل يده يابسة.","3:2":"فصاروا يراقبونه: هل يشفيه في السبت؟ لكي يشتكوا عليه.","3:3":"فقال للرجل الذي له اليد اليابسة: «قم في الوسط!»","3:4":"ثم قال لهم: «هل يحل في السبت فعل الخير أو فعل الشر؟ تخليص نفس أو قتل؟». فسكتوا.","3:5":"فنظر حوله إليهم بغضب, حزينا على غلاظة قلوبهم, وقال للرجل: «مد يدك». فمدها, فعادت يده صحيحة كالأخرى.","3:6":"فخرج الفريسيون للوقت مع الهيرودسيين وتشاوروا عليه لكي يهلكوه.","3:7":"فانصرف يسوع مع تلاميذه إلى البحر, وتبعه جمع كثير من الجليل ومن اليهودية","3:8":"ومن أورشليم ومن أدومية ومن عبر الأردن. والذين حول صور وصيداء, جمع كثير, إذ سمعوا كم صنع أتوا إليه.","3:9":"فقال لتلاميذه أن تلازمه سفينة صغيرة لسبب الجمع, كي لا يزحموه","3:10":"لأنه كان قد شفى كثيرين, حتى وقع عليه ليلمسه كل من فيه داء.","3:11":"والأرواح النجسة حينما نظرته خرت له وصرخت قائلة: «إنك أنت ابن الله!»","3:12":"وأوصاهم كثيرا أن لا يظهروه.","3:13":"ثم صعد إلى الجبل ودعا الذين أرادهم فذهبوا إليه.","3:14":"وأقام اثني عشر ليكونوا معه, وليرسلهم ليكرزوا","3:15":"ويكون لهم سلطان على شفاء الأمراض وإخراج الشياطين.","3:16":"وجعل لسمعان اسم بطرس.","3:17":"ويعقوب بن زبدي ويوحنا أخا يعقوب, وجعل لهما اسم بوانرجس (أي ابني الرعد).","3:18":"وأندراوس, وفيلبس, وبرثولماوس, ومتى, وتوما, ويعقوب بن حلفى, وتداوس, وسمعان القانوي","3:19":"ويهوذا الإسخريوطي الذي أسلمه. ثم أتوا إلى بيت.","3:20":"فاجتمع أيضا جمع حتى لم يقدروا ولا على أكل خبز.","3:21":"ولما سمع أقرباؤه خرجوا ليمسكوه, لأنهم قالوا: «إنه مختل!».","3:22":"وأما الكتبة الذين نزلوا من أورشليم فقالوا: «إن معه بعلزبول وإنه برئيس الشياطين يخرج الشياطين».","3:23":"فدعاهم وقال لهم بأمثال: «كيف يقدر شيطان أن يخرج شيطانا؟","3:24":"وإن انقسمت مملكة على ذاتها لا تقدر تلك المملكة أن تثبت.","3:25":"وإن انقسم بيت على ذاته لا يقدر ذلك البيت أن يثبت.","3:26":"وإن قام الشيطان على ذاته وانقسم لا يقدر أن يثبت, بل يكون له انقضاء.","3:27":"لا يستطيع أحد أن يدخل بيت قوي وينهب أمتعته, إن لم يربط القوي أولا, وحينئذ ينهب بيته.","3:28":"الحق أقول لكم: إن جميع الخطايا تغفر لبني البشر, والتجاديف التي يجدفونها.","3:29":"ولكن من جدف على الروح القدس فليس له مغفرة إلى الأبد, بل هو مستوجب دينونة أبدية».","3:30":"لأنهم قالوا: «إن معه روحا نجسا».","3:31":"فجاءت حينئذ إخوته وأمه ووقفوا خارجا وأرسلوا إليه يدعونه.","3:32":"وكان الجمع جالسا حوله, فقالوا له: «هوذا أمك وإخوتك خارجا يطلبونك».","3:33":"فأجابهم قائلا: «من أمي وإخوتي؟»","3:34":"ثم نظر حوله إلى الجالسين وقال: «ها أمي وإخوتي","3:35":"لأن من يصنع مشيئة الله هو أخي وأختي وأمي».","4:1":"وابتدأ أيضا يعلم عند البحر, فاجتمع إليه جمع كثير حتى إنه دخل السفينة وجلس على البحر, والجمع كله كان عند البحر على الأرض.","4:2":"فكان يعلمهم كثيرا بأمثال. وقال لهم في تعليمه:","4:3":"«اسمعوا. هوذا الزارع قد خرج ليزرع","4:4":"وفيما هو يزرع سقط بعض على الطريق, فجاءت طيور السماء وأكلته.","4:5":"وسقط آخر على مكان محجر, حيث لم تكن له تربة كثيرة, فنبت حالا إذ لم يكن له عمق أرض.","4:6":"ولكن لما أشرقت الشمس احترق, وإذ لم يكن له أصل جف.","4:7":"وسقط آخر في الشوك, فطلع الشوك وخنقه فلم يعط ثمرا.","4:8":"وسقط آخر في الأرض الجيدة, فأعطى ثمرا يصعد وينمو, فأتى واحد بثلاثين وآخر بستين وآخر بمئة».","4:9":"ثم قال لهم: «من له أذنان للسمع, فليسمع!»","4:10":"ولما كان وحده سأله الذين حوله مع الاثني عشر عن المثل","4:11":"فقال لهم: «قد أعطي لكم أن تعرفوا سر ملكوت الله. وأما الذين هم من خارج فبالأمثال يكون لهم كل شيء","4:12":"لكي يبصروا مبصرين ولا ينظروا, ويسمعوا سامعين ولا يفهموا, لئلا يرجعوا فتغفر لهم خطاياهم».","4:13":"ثم قال لهم: «أما تعلمون هذا المثل؟ فكيف تعرفون جميع الأمثال؟","4:14":"الزارع يزرع الكلمة.","4:15":"وهؤلاء هم الذين على الطريق: حيث تزرع الكلمة, وحينما يسمعون يأتي الشيطان للوقت وينزع الكلمة المزروعة في قلوبهم.","4:16":"وهؤلاء كذلك هم الذين زرعوا على الأماكن المحجرة: الذين حينما يسمعون الكلمة يقبلونها للوقت بفرح","4:17":"ولكن ليس لهم أصل في ذواتهم, بل هم إلى حين. فبعد ذلك إذا حدث ضيق أو اضطهاد من أجل الكلمة, فللوقت يعثرون.","4:18":"وهؤلاء هم الذين زرعوا بين الشوك: هؤلاء هم الذين يسمعون الكلمة","4:19":"وهموم هذا العالم وغرور الغنى وشهوات سائر الأشياء تدخل وتخنق الكلمة فتصير بلا ثمر.","4:20":"وهؤلاء هم الذين زرعوا على الأرض الجيدة: الذين يسمعون الكلمة ويقبلونها, ويثمرون واحد ثلاثين وآخر ستين وآخر مئة».","4:21":"ثم قال لهم: «هل يؤتى بسراج ليوضع تحت المكيال أو تحت السرير؟ أليس ليوضع على المنارة؟","4:22":"لأنه ليس شيء خفي لا يظهر, ولا صار مكتوما إلا ليعلن.","4:23":"إن كان لأحد أذنان للسمع, فليسمع!»","4:24":"وقال لهم: «انظروا ما تسمعون! بالكيل الذي به تكيلون يكال لكم ويزاد لكم أيها السامعون.","4:25":"لأن من له سيعطى, وأما من ليس له فالذي عنده سيؤخذ منه».","4:26":"وقال: «هكذا ملكوت الله: كأن إنسانا يلقي البذار على الأرض","4:27":"وينام ويقوم ليلا ونهارا, والبذار يطلع وينمو, وهو لا يعلم كيف","4:28":"لأن الأرض من ذاتها تأتي بثمر. أولا نباتا, ثم سنبلا, ثم قمحا ملآن في السنبل.","4:29":"وأما متى أدرك الثمر, فللوقت يرسل المنجل لأن الحصاد قد حضر».","4:30":"وقال: «بماذا نشبه ملكوت الله أو بأي مثل نمثله؟","4:31":"مثل حبة خردل, متى زرعت في الأرض فهي أصغر جميع البزور التي على الأرض.","4:32":"ولكن متى زرعت تطلع وتصير أكبر جميع البقول, وتصنع أغصانا كبيرة, حتى تستطيع طيور السماء أن تتآوى تحت ظلها».","4:33":"وبأمثال كثيرة مثل هذه كان يكلمهم حسبما كانوا يستطيعون أن يسمعوا","4:34":"وبدون مثل لم يكن يكلمهم. وأما على انفراد فكان يفسر لتلاميذه كل شيء.","4:35":"وقال لهم في ذلك اليوم لما كان المساء: «لنجتز إلى العبر».","4:36":"فصرفوا الجمع وأخذوه كما كان في السفينة. وكانت معه أيضا سفن أخرى صغيرة.","4:37":"فحدث نوء ريح عظيم, فكانت الأمواج تضرب إلى السفينة حتى صارت تمتلئ.","4:38":"وكان هو في المؤخر على وسادة نائما. فأيقظوه وقالوا له: «يا معلم, أما يهمك أننا نهلك؟»","4:39":"فقام وانتهر الريح, وقال للبحر: «اسكت. ابكم». فسكنت الريح وصار هدوء عظيم.","4:40":"وقال لهم: «ما بالكم خائفين هكذا؟ كيف لا إيمان لكم؟»","4:41":"فخافوا خوفا عظيما, وقالوا بعضهم لبعض: «من هو هذا؟ فإن الريح أيضا والبحر يطيعانه!».","5:1":"وجاءوا إلى عبر البحر إلى كورة الجدريين.","5:2":"ولما خرج من السفينة للوقت استقبله من القبور إنسان به روح نجس","5:3":"كان مسكنه في القبور, ولم يقدر أحد أن يربطه ولا بسلاسل","5:4":"لأنه قد ربط كثيرا بقيود وسلاسل فقطع السلاسل وكسر القيود, فلم يقدر أحد أن يذلله.","5:5":"وكان دائما ليلا ونهارا في الجبال وفي القبور, يصيح ويجرح نفسه بالحجارة.","5:6":"فلما رأى يسوع من بعيد ركض وسجد له","5:7":"وصرخ بصوت عظيم وقال: «ما لي ولك يا يسوع ابن الله العلي! أستحلفك بالله أن لا تعذبني!»","5:8":"لأنه قال له: «اخرج من الإنسان يا أيها الروح النجس».","5:9":"وسأله: «ما اسمك؟» فأجاب قائلا: «اسمي لجئون, لأننا كثيرون».","5:10":"وطلب إليه كثيرا أن لا يرسلهم إلى خارج الكورة.","5:11":"وكان هناك عند الجبال قطيع كبير من الخنازير يرعى","5:12":"فطلب إليه كل الشياطين قائلين: «أرسلنا إلى الخنازير لندخل فيها».","5:13":"فأذن لهم يسوع للوقت. فخرجت الأرواح النجسة ودخلت في الخنازير, فاندفع القطيع من على الجرف إلى البحر - وكان نحو ألفين, فاختنق في البحر.","5:14":"وأما رعاة الخنازير فهربوا وأخبروا في المدينة وفي الضياع فخرجوا ليروا ما جرى.","5:15":"وجاءوا إلى يسوع فنظروا المجنون الذي كان فيه اللجئون جالسا ولابسا وعاقلا, فخافوا.","5:16":"فحدثهم الذين رأوا كيف جرى للمجنون وعن الخنازير.","5:17":"فابتدأوا يطلبون إليه أن يمضي من تخومهم.","5:18":"ولما دخل السفينة طلب إليه الذي كان مجنونا أن يكون معه","5:19":"فلم يدعه يسوع, بل قال له: «اذهب إلى بيتك وإلى أهلك, وأخبرهم كم صنع الرب بك ورحمك».","5:20":"فمضى وابتدأ ينادي في العشر المدن كم صنع به يسوع. فتعجب الجميع.","5:21":"ولما اجتاز يسوع في السفينة أيضا إلى العبر, اجتمع إليه جمع كثير, وكان عند البحر.","5:22":"وإذا واحد من رؤساء المجمع اسمه يايرس جاء. ولما رآه خر عند قدميه","5:23":"وطلب إليه كثيرا قائلا: «ابنتي الصغيرة على آخر نسمة. ليتك تأتي وتضع يدك عليها لتشفى فتحيا».","5:24":"فمضى معه وتبعه جمع كثير وكانوا يزحمونه.","5:25":"وامرأة بنزف دم منذ اثنتي عشرة سنة","5:26":"وقد تألمت كثيرا من أطباء كثيرين, وأنفقت كل ما عندها ولم تنتفع شيئا, بل صارت إلى حال أردأ -","5:27":"لما سمعت بيسوع, جاءت في الجمع من وراء, ومست ثوبه","5:28":"لأنها قالت: «إن مسست ولو ثيابه شفيت».","5:29":"فللوقت جف ينبوع دمها, وعلمت في جسمها أنها قد برئت من الداء.","5:30":"فللوقت التفت يسوع بين الجمع شاعرا في نفسه بالقوة التي خرجت منه, وقال: «من لمس ثيابي؟»","5:31":"فقال له تلاميذه: «أنت تنظر الجمع يزحمك, وتقول من لمسني؟»","5:32":"وكان ينظر حوله ليرى التي فعلت هذا.","5:33":"وأما المرأة فجاءت وهي خائفة ومرتعدة, عالمة بما حصل لها, فخرت وقالت له الحق كله.","5:34":"فقال لها: «يا ابنة, إيمانك قد شفاك. اذهبي بسلام وكوني صحيحة من دائك».","5:35":"وبينما هو يتكلم جاءوا من دار رئيس المجمع قائلين: «ابنتك ماتت. لماذا تتعب المعلم بعد؟»","5:36":"فسمع يسوع لوقته الكلمة التي قيلت, فقال لرئيس المجمع: «لا تخف. آمن فقط».","5:37":"ولم يدع أحدا يتبعه إلا بطرس ويعقوب, ويوحنا أخا يعقوب.","5:38":"فجاء إلى بيت رئيس المجمع ورأى ضجيجا. يبكون ويولولون كثيرا.","5:39":"فدخل وقال لهم: «لماذا تضجون وتبكون؟ لم تمت الصبية لكنها نائمة».","5:40":"فضحكوا عليه. أما هو فأخرج الجميع, وأخذ أبا الصبية وأمها والذين معه ودخل حيث كانت الصبية مضطجعة","5:41":"وأمسك بيد الصبية وقال لها: «طليثا, قومي». (الذي تفسيره: يا صبية, لك أقول قومي).","5:42":"وللوقت قامت الصبية ومشت, لأنها كانت ابنة اثنتي عشرة سنة. فبهتوا بهتا عظيما.","5:43":"فأوصاهم كثيرا أن لا يعلم أحد بذلك. وقال أن تعطى لتأكل.","6:1":"وخرج من هناك وجاء إلى وطنه وتبعه تلاميذه.","6:2":"ولما كان السبت, ابتدأ يعلم في المجمع. وكثيرون إذ سمعوا بهتوا قائلين: «من أين لهذا هذه؟ وما هذه الحكمة التي أعطيت له حتى تجري على يديه قوات مثل هذه؟","6:3":"أليس هذا هو النجار ابن مريم, وأخو يعقوب ويوسي ويهوذا وسمعان؟ أوليست أخواته ههنا عندنا؟» فكانوا يعثرون به.","6:4":"فقال لهم يسوع: «ليس نبي بلا كرامة إلا في وطنه وبين أقربائه وفي بيته».","6:5":"ولم يقدر أن يصنع هناك ولا قوة واحدة, غير أنه وضع يديه على مرضى قليلين فشفاهم.","6:6":"وتعجب من عدم إيمانهم. وصار يطوف القرى المحيطة يعلم.","6:7":"ودعا الاثني عشر وابتدأ يرسلهم اثنين اثنين, وأعطاهم سلطانا على الأرواح النجسة","6:8":"وأوصاهم أن لا يحملوا شيئا للطريق غير عصا فقط, لا مزودا ولا خبزا ولا نحاسا في المنطقة.","6:9":"بل يكونوا مشدودين بنعال, ولا يلبسوا ثوبين.","6:10":"وقال لهم: «حيثما دخلتم بيتا فأقيموا فيه حتى تخرجوا من هناك.","6:11":"وكل من لا يقبلكم ولا يسمع لكم, فاخرجوا من هناك وانفضوا التراب الذي تحت أرجلكم شهادة عليهم. الحق أقول لكم: ستكون لأرض سدوم وعمورة يوم الدين حالة أكثر احتمالا مما لتلك المدينة».","6:12":"فخرجوا وصاروا يكرزون أن يتوبوا.","6:13":"وأخرجوا شياطين كثيرة, ودهنوا بزيت مرضى كثيرين فشفوهم.","6:14":"فسمع هيرودس الملك, لأن اسمه صار مشهورا. وقال: «إن يوحنا المعمدان قام من الأموات ولذلك تعمل به القوات».","6:15":"قال آخرون: «إنه إيليا». وقال آخرون: «إنه نبي أو كأحد الأنبياء».","6:16":"ولكن لما سمع هيرودس قال: «هذا هو يوحنا الذي قطعت أنا رأسه. إنه قام من الأموات!»","6:17":"لأن هيرودس نفسه كان قد أرسل وأمسك يوحنا وأوثقه في السجن من أجل هيروديا امرأة فيلبس أخيه, إذ كان قد تزوج بها.","6:18":"لأن يوحنا كان يقول لهيرودس: «لا يحل أن تكون لك امرأة أخيك!»","6:19":"فحنقت هيروديا عليه, وأرادت أن تقتله ولم تقدر","6:20":"لأن هيرودس كان يهاب يوحنا عالما أنه رجل بار وقديس, وكان يحفظه. وإذ سمعه, فعل كثيرا, وسمعه بسرور.","6:21":"وإذ كان يوم موافق, لما صنع هيرودس في مولده عشاء لعظمائه وقواد الألوف ووجوه الجليل","6:22":"دخلت ابنة هيروديا ورقصت, فسرت هيرودس والمتكئين معه. فقال الملك للصبية: «مهما أردت اطلبي مني فأعطيك».","6:23":"وأقسم لها أن «مهما طلبت مني لأعطينك حتى نصف مملكتي».","6:24":"فخرجت وقالت لأمها: «ماذا أطلب؟» فقالت: «رأس يوحنا المعمدان».","6:25":"فدخلت للوقت بسرعة إلى الملك وطلبت قائلة: «أريد أن تعطيني حالا رأس يوحنا المعمدان على طبق».","6:26":"فحزن الملك جدا. ولأجل الأقسام والمتكئين لم يرد أن يردها.","6:27":"فللوقت أرسل الملك سيافا وأمر أن يؤتى برأسه.","6:28":"فمضى وقطع رأسه في السجن. وأتى برأسه على طبق وأعطاه للصبية, والصبية أعطته لأمها.","6:29":"ولما سمع تلاميذه, جاءوا ورفعوا جثته ووضعوها في قبر.","6:30":"واجتمع الرسل إلى يسوع وأخبروه بكل شيء, كل ما فعلوا وكل ما علموا.","6:31":"فقال لهم: «تعالوا أنتم منفردين إلى موضع خلاء واستريحوا قليلا». لأن القادمين والذاهبين كانوا كثيرين, ولم تتيسر لهم فرصة للأكل.","6:32":"فمضوا في السفينة إلى موضع خلاء منفردين.","6:33":"فرآهم الجموع منطلقين, وعرفه كثيرون. فتراكضوا إلى هناك من جميع المدن مشاة, وسبقوهم واجتمعوا إليه.","6:34":"فلما خرج يسوع رأى جمعا كثيرا, فتحنن عليهم إذ كانوا كخراف لا راعي لها, فابتدأ يعلمهم كثيرا.","6:35":"وبعد ساعات كثيرة تقدم إليه تلاميذه قائلين: «الموضع خلاء والوقت مضى.","6:36":"اصرفهم لكي يمضوا إلى الضياع والقرى حوالينا ويبتاعوا لهم خبزا, لأن ليس عندهم ما يأكلون».","6:37":"فأجاب وقال لهم: «أعطوهم أنتم ليأكلوا». فقالوا له: «أنمضي ونبتاع خبزا بمئتي دينار ونعطيهم ليأكلوا؟»","6:38":"فقال لهم: «كم رغيفا عندكم؟ اذهبوا وانظروا». ولما علموا قالوا: «خمسة وسمكتان».","6:39":"فأمرهم أن يجعلوا الجميع يتكئون رفاقا رفاقا على العشب الأخضر.","6:40":"فاتكأوا صفوفا صفوفا: مئة مئة وخمسين خمسين.","6:41":"فأخذ الأرغفة الخمسة والسمكتين, ورفع نظره نحو السماء, وبارك ثم كسر الأرغفة, وأعطى تلاميذه ليقدموا إليهم, وقسم السمكتين للجميع","6:42":"فأكل الجميع وشبعوا","6:43":"ثم رفعوا من الكسر اثنتي عشرة قفة مملوة, ومن السمك.","6:44":"وكان الذين أكلوا من الأرغفة نحو خمسة آلاف رجل.","6:45":"وللوقت ألزم تلاميذه أن يدخلوا السفينة ويسبقوا إلى العبر, إلى بيت صيدا, حتى يكون قد صرف الجمع.","6:46":"وبعدما ودعهم مضى إلى الجبل ليصلي.","6:47":"ولما صار المساء كانت السفينة في وسط البحر, وهو على البر وحده.","6:48":"ورآهم معذبين في الجذف, لأن الريح كانت ضدهم. ونحو الهزيع الرابع من الليل أتاهم ماشيا على البحر, وأراد أن يتجاوزهم.","6:49":"فلما رأوه ماشيا على البحر ظنوه خيالا, فصرخوا","6:50":"لأن الجميع رأوه واضطربوا. فللوقت كلمهم وقال لهم: «ثقوا. أنا هو. لا تخافوا».","6:51":"فصعد إليهم إلى السفينة فسكنت الريح, فبهتوا وتعجبوا في أنفسهم جدا إلى الغاية","6:52":"لأنهم لم يفهموا بالأرغفة إذ كانت قلوبهم غليظة.","6:53":"فلما عبروا جاءوا إلى أرض جنيسارت وأرسوا.","6:54":"ولما خرجوا من السفينة للوقت عرفوه","6:55":"فطافوا جميع تلك الكورة المحيطة, وابتدأوا يحملون المرضى على أسرة إلى حيث سمعوا أنه هناك.","6:56":"وحيثما دخل إلى قرى أو مدن أو ضياع, وضعوا المرضى في الأسواق, وطلبوا إليه أن يلمسوا ولو هدب ثوبه. وكل من لمسه شفي!","7:1":"واجتمع إليه الفريسيون وقوم من الكتبة قادمين من أورشليم.","7:2":"ولما رأوا بعضا من تلاميذه يأكلون خبزا بأيد دنسة, أي غير مغسولة, لاموا -","7:3":"لأن الفريسيين وكل اليهود إن لم يغسلوا أيديهم باعتناء, لا يأكلون, متمسكين بتقليد الشيوخ.","7:4":"ومن السوق إن لم يغتسلوا لا يأكلون. وأشياء أخرى كثيرة تسلموها للتمسك بها, من غسل كؤوس وأباريق وآنية نحاس وأسرة.","7:5":"ثم سأله الفريسيون والكتبة: «لماذا لا يسلك تلاميذك حسب تقليد الشيوخ, بل يأكلون خبزا بأيد غير مغسولة؟»","7:6":"فأجاب وقال لهم: «حسنا تنبأ إشعياء عنكم أنتم المرائين كما هو مكتوب: هذا الشعب يكرمني بشفتيه, وأما قلبه فمبتعد عني بعيدا","7:7":"وباطلا يعبدونني وهم يعلمون تعاليم هي وصايا الناس.","7:8":"لأنكم تركتم وصية الله وتتمسكون بتقليد الناس: غسل الأباريق والكؤوس, وأمورا أخر كثيرة مثل هذه تفعلون».","7:9":"ثم قال لهم: «حسنا! رفضتم وصية الله لتحفظوا تقليدكم.","7:10":"لأن موسى قال: أكرم أباك وأمك, ومن يشتم أبا أو أما فليمت موتا.","7:11":"وأما أنتم فتقولون: إن قال إنسان لأبيه أو أمه: قربان, أي هدية, هو الذي تنتفع به مني","7:12":"فلا تدعونه في ما بعد يفعل شيئا لأبيه أو أمه.","7:13":"مبطلين كلام الله بتقليدكم الذي سلمتموه. وأمورا كثيرة مثل هذه تفعلون».","7:14":"ثم دعا كل الجمع وقال لهم: «اسمعوا مني كلكم وافهموا.","7:15":"ليس شيء من خارج الإنسان إذا دخل فيه يقدر أن ينجسه, لكن الأشياء التي تخرج منه هي التي تنجس الإنسان.","7:16":"إن كان لأحد أذنان للسمع, فليسمع».","7:17":"ولما دخل من عند الجمع إلى البيت, سأله تلاميذه عن المثل.","7:18":"فقال لهم: «أفأنتم أيضا هكذا غير فاهمين؟ أما تفهمون أن كل ما يدخل الإنسان من خارج لا يقدر أن ينجسه","7:19":"لأنه لا يدخل إلى قلبه بل إلى الجوف, ثم يخرج إلى الخلاء, وذلك يطهر كل الأطعمة».","7:20":"ثم قال: «إن الذي يخرج من الإنسان ذلك ينجس الإنسان.","7:21":"لأنه من الداخل, من قلوب الناس, تخرج الأفكار الشريرة: زنى, فسق, قتل","7:22":"سرقة, طمع, خبث, مكر, عهارة, عين شريرة, تجديف, كبرياء, جهل.","7:23":"جميع هذه الشرور تخرج من الداخل وتنجس الإنسان».","7:24":"ثم قام من هناك ومضى إلى تخوم صور وصيداء, ودخل بيتا وهو يريد أن لا يعلم أحد, فلم يقدر أن يختفي","7:25":"لأن امرأة كان بابنتها روح نجس سمعت به, فأتت وخرت عند قدميه.","7:26":"وكانت الامرأة أممية, وفي جنسها فينيقية سورية - فسألته أن يخرج الشيطان من ابنتها.","7:27":"وأما يسوع فقال لها: «دعي البنين أولا يشبعون, لأنه ليس حسنا أن يؤخذ خبز البنين ويطرح للكلاب».","7:28":"فأجابت وقالت له: «نعم, يا سيد! والكلاب أيضا تحت المائدة تأكل من فتات البنين».","7:29":"فقال لها: «لأجل هذه الكلمة, اذهبي. قد خرج الشيطان من ابنتك».","7:30":"فذهبت إلى بيتها ووجدت الشيطان قد خرج, والابنة مطروحة على الفراش.","7:31":"ثم خرج أيضا من تخوم صور وصيداء, وجاء إلى بحر الجليل في وسط حدود المدن العشر.","7:32":"وجاءوا إليه بأصم أعقد, وطلبوا إليه أن يضع يده عليه.","7:33":"فأخذه من بين الجمع على ناحية, ووضع أصابعه في أذنيه وتفل ولمس لسانه","7:34":"ورفع نظره نحو السماء, وأن وقال له: «إفثا». أي انفتح.","7:35":"وللوقت انفتحت أذناه, وانحل رباط لسانه, وتكلم مستقيما.","7:36":"فأوصاهم أن لا يقولوا لأحد. ولكن على قدر ما أوصاهم كانوا ينادون أكثر كثيرا.","7:37":"وبهتوا إلى الغاية قائلين: «إنه عمل كل شيء حسنا! جعل الصم يسمعون والخرس يتكلمون!».","8:1":"في تلك الأيام إذ كان الجمع كثيرا جدا, ولم يكن لهم ما يأكلون, دعا يسوع تلاميذه وقال لهم:","8:2":"«إني أشفق على الجمع, لأن الآن لهم ثلاثة أيام يمكثون معي وليس لهم ما يأكلون.","8:3":"وإن صرفتهم إلى بيوتهم صائمين يخورون في الطريق, لأن قوما منهم جاءوا من بعيد».","8:4":"فأجابه تلاميذه: «من أين يستطيع أحد أن يشبع هؤلاء خبزا هنا في البرية؟»","8:5":"فسألهم: «كم عندكم من الخبز؟» فقالوا: «سبعة».","8:6":"فأمر الجمع أن يتكئوا على الأرض, وأخذ السبع خبزات وشكر وكسر وأعطى تلاميذه ليقدموا, فقدموا إلى الجمع.","8:7":"وكان معهم قليل من صغار السمك, فبارك وقال أن يقدموا هذه أيضا.","8:8":"فأكلوا وشبعوا ثم رفعوا فضلات الكسر: سبعة سلال.","8:9":"وكان الآكلون نحو أربعة آلاف. ثم صرفهم.","8:10":"وللوقت دخل السفينة مع تلاميذه وجاء إلى نواحي دلمانوثة.","8:11":"فخرج الفريسيون وابتدأوا يحاورونه طالبين منه آية من السماء, لكي يجربوه.","8:12":"فتنهد بروحه وقال: «لماذا يطلب هذا الجيل آية؟ الحق أقول لكم: لن يعطى هذا الجيل آية!»","8:13":"ثم تركهم ودخل أيضا السفينة ومضى إلى العبر.","8:14":"ونسوا أن يأخذوا خبزا, ولم يكن معهم في السفينة إلا رغيف واحد.","8:15":"وأوصاهم قائلا: «انظروا وتحرزوا من خمير الفريسيين وخمير هيرودس.","8:16":"ففكروا قائلين بعضهم لبعض: «ليس عندنا خبز».","8:17":"فعلم يسوع وقال لهم: «لماذا تفكرون أن ليس عندكم خبز؟ ألا تشعرون بعد ولا تفهمون؟ أحتى الآن قلوبكم غليظة؟","8:18":"ألكم أعين ولا تبصرون, ولكم آذان ولا تسمعون, ولا تذكرون؟","8:19":"حين كسرت الأرغفة الخمسة للخمسة الآلاف, كم قفة مملوة كسرا رفعتم؟» قالوا له: «اثنتي عشرة».","8:20":"«وحين السبعة للأربعة الآلاف, كم سل كسر مملوا رفعتم؟» قالوا: «سبعة».","8:21":"فقال لهم: «كيف لا تفهمون؟»","8:22":"وجاء إلى بيت صيدا, فقدموا إليه أعمى وطلبوا إليه أن يلمسه","8:23":"فأخذ بيد الأعمى وأخرجه إلى خارج القرية, وتفل في عينيه, ووضع يديه عليه وسأله هل أبصر شيئا؟","8:24":"فتطلع وقال: «أبصر الناس كأشجار يمشون».","8:25":"ثم وضع يديه أيضا على عينيه, وجعله يتطلع. فعاد صحيحا وأبصر كل إنسان جليا.","8:26":"فأرسله إلى بيته قائلا: «لا تدخل القرية, ولا تقل لأحد في القرية».","8:27":"ثم خرج يسوع وتلاميذه إلى قرى قيصرية فيلبس. وفي الطريق سأل تلاميذه قائلا لهم: «من يقول الناس إني أنا؟»","8:28":"فأجابوا: «يوحنا المعمدان وآخرون إيليا وآخرون واحد من الأنبياء».","8:29":"فقال لهم: «وأنتم, من تقولون إني أنا؟» فأجاب بطرس وقال له: «أنت المسيح!»","8:30":"فانتهرهم كي لا يقولوا لأحد عنه.","8:31":"وابتدأ يعلمهم أن ابن الإنسان ينبغي أن يتألم كثيرا, ويرفض من الشيوخ ورؤساء الكهنة والكتبة, ويقتل, وبعد ثلاثة أيام يقوم.","8:32":"وقال القول علانية فأخذه بطرس إليه وابتدأ ينتهره.","8:33":"فالتفت وأبصر تلاميذه, فانتهر بطرس قائلا: «اذهب عني يا شيطان لأنك لا تهتم بما لله لكن بما للناس».","8:34":"ودعا الجمع مع تلاميذه وقال لهم: «من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني.","8:35":"فإن من أراد أن يخلص نفسه يهلكها, ومن يهلك نفسه من أجلي ومن أجل الإنجيل فهو يخلصها.","8:36":"لأنه ماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه؟","8:37":"أو ماذا يعطي الإنسان فداء عن نفسه؟","8:38":"لأن من استحى بي وبكلامي في هذا الجيل الفاسق الخاطئ, فإن ابن الإنسان يستحي به متى جاء بمجد أبيه مع الملائكة القديسين».","9:1":"وقال لهم: «الحق أقول لكم: إن من القيام ههنا قوما لا يذوقون الموت حتى يروا ملكوت الله قد أتى بقوة».","9:2":"وبعد ستة أيام أخذ يسوع بطرس ويعقوب ويوحنا, وصعد بهم إلى جبل عال منفردين وحدهم. وتغيرت هيئته قدامهم","9:3":"وصارت ثيابه تلمع بيضاء جدا كالثلج, لا يقدر قصار على الأرض أن يبيض مثل ذلك.","9:4":"وظهر لهم إيليا مع موسى, وكانا يتكلمان مع يسوع.","9:5":"فجعل بطرس يقول ليسوع: «يا سيدي, جيد أن نكون ههنا. فلنصنع ثلاث مظال لك واحدة, ولموسى واحدة, ولإيليا واحدة».","9:6":"لأنه لم يكن يعلم ما يتكلم به إذ كانوا مرتعبين.","9:7":"وكانت سحابة تظللهم. فجاء صوت من السحابة قائلا: «هذا هو ابني الحبيب. له اسمعوا».","9:8":"فنظروا حولهم بغتة ولم يروا أحدا غير يسوع وحده معهم.","9:9":"وفيما هم نازلون من الجبل, أوصاهم أن لا يحدثوا أحدا بما أبصروا, إلا متى قام ابن الإنسان من الأموات.","9:10":"فحفظوا الكلمة لأنفسهم يتساءلون: «ما هو القيام من الأموات؟»","9:11":"فسألوه قائلين: «لماذا يقول الكتبة إن إيليا ينبغي أن يأتي أولا؟»","9:12":"فأجاب وقال لهم: «إن إيليا يأتي أولا ويرد كل شيء. وكيف هو مكتوب عن ابن الإنسان أن يتألم كثيرا ويرذل.","9:13":"لكن أقول لكم: إن إيليا أيضا قد أتى, وعملوا به كل ما أرادوا, كما هو مكتوب عنه».","9:14":"ولما جاء إلى التلاميذ رأى جمعا كثيرا حولهم وكتبة يحاورونهم.","9:15":"وللوقت كل الجمع لما رأوه تحيروا, وركضوا وسلموا عليه.","9:16":"فسأل الكتبة: «بماذا تحاورونهم؟»","9:17":"فأجاب واحد من الجمع وقال: «يا معلم, قد قدمت إليك ابني به روح أخرس","9:18":"وحيثما أدركه يمزقه فيزبد ويصر بأسنانه وييبس. فقلت لتلاميذك أن يخرجوه فلم يقدروا».","9:19":"فأجاب وقال لهم: «أيها الجيل غير المؤمن, إلى متى أكون معكم؟ إلى متى أحتملكم؟ قدموه إلي!».","9:20":"فقدموه إليه. فلما رآه للوقت صرعه الروح, فوقع على الأرض يتمرغ ويزبد.","9:21":"فسأل أباه: «كم من الزمان منذ أصابه هذا؟» فقال: «منذ صباه.","9:22":"وكثيرا ما ألقاه في النار وفي الماء ليهلكه. لكن إن كنت تستطيع شيئا فتحنن علينا وأعنا».","9:23":"فقال له يسوع: «إن كنت تستطيع أن تؤمن كل شيء مستطاع للمؤمن».","9:24":"فللوقت صرخ أبو الولد بدموع وقال: «أومن يا سيد, فأعن عدم إيماني».","9:25":"فلما رأى يسوع أن الجمع يتراكضون, انتهر الروح النجس قائلا له: «أيها الروح الأخرس الأصم, أنا آمرك: اخرج منه ولا تدخله أيضا!»","9:26":"فصرخ وصرعه شديدا وخرج فصار كميت, حتى قال كثيرون: إنه مات.","9:27":"فأمسكه يسوع بيده وأقامه, فقام.","9:28":"ولما دخل بيتا سأله تلاميذه على انفراد: «لماذا لم نقدر نحن أن نخرجه؟»","9:29":"فقال لهم: «هذا الجنس لا يمكن أن يخرج بشيء إلا بالصلاة والصوم».","9:30":"وخرجوا من هناك واجتازوا الجليل, ولم يرد أن يعلم أحد","9:31":"لأنه كان يعلم تلاميذه ويقول لهم إن ابن الإنسان يسلم إلى أيدي الناس فيقتلونه وبعد أن يقتل يقوم في اليوم الثالث.","9:32":"وأما هم فلم يفهموا القول, وخافوا أن يسألوه.","9:33":"وجاء إلى كفرناحوم. وإذ كان في البيت سألهم: «بماذا كنتم تتكالمون فيما بينكم في الطريق؟»","9:34":"فسكتوا, لأنهم تحاجوا في الطريق بعضهم مع بعض في من هو أعظم.","9:35":"فجلس ونادى الاثني عشر وقال لهم: «إذا أراد أحد أن يكون أولا فيكون آخر الكل وخادما للكل».","9:36":"فأخذ ولدا وأقامه في وسطهم ثم احتضنه وقال لهم:","9:37":"«من قبل واحدا من أولاد مثل هذا باسمي يقبلني, ومن قبلني فليس يقبلني أنا بل الذي أرسلني».","9:38":"فأجابه يوحنا قائلا: «يا معلم, رأينا واحدا يخرج شياطين باسمك وهو ليس يتبعنا, فمنعناه لأنه ليس يتبعنا».","9:39":"فقال يسوع: «لا تمنعوه, لأنه ليس أحد يصنع قوة باسمي ويستطيع سريعا أن يقول علي شرا.","9:40":"لأن من ليس علينا فهو معنا.","9:41":"لأن من سقاكم كأس ماء باسمي لأنكم للمسيح, فالحق أقول لكم إنه لا يضيع أجره.","9:42":"ومن أعثر أحد الصغار المؤمنين بي, فخير له لو طوق عنقه بحجر رحى وطرح في البحر.","9:43":"وإن أعثرتك يدك فاقطعها. خير لك أن تدخل الحياة أقطع من أن تكون لك يدان وتمضي إلى جهنم, إلى النار التي لا تطفأ","9:44":"حيث دودهم لا يموت والنار لا تطفأ.","9:45":"وإن أعثرتك رجلك فاقطعها. خير لك أن تدخل الحياة أعرج من أن تكون لك رجلان وتطرح في جهنم في النار التي لا تطفأ","9:46":"حيث دودهم لا يموت والنار لا تطفأ.","9:47":"وإن أعثرتك عينك فاقلعها. خير لك أن تدخل ملكوت الله أعور من أن تكون لك عينان وتطرح في جهنم النار","9:48":"حيث دودهم لا يموت والنار لا تطفأ.","9:49":"لأن كل واحد يملح بنار, وكل ذبيحة تملح بملح.","9:50":"الملح جيد. ولكن إذا صار الملح بلا ملوحة, فبماذا تصلحونه؟ ليكن لكم في أنفسكم ملح, وسالموا بعضكم بعضا».","10:1":"وقام من هناك وجاء إلى تخوم اليهودية من عبر الأردن فاجتمع إليه جموع أيضا, وكعادته كان أيضا يعلمهم.","10:2":"فتقدم الفريسيون وسألوه: «هل يحل للرجل أن يطلق امرأته؟» ليجربوه.","10:3":"فأجاب وقال لهم: «بماذا أوصاكم موسى؟»","10:4":"فقالوا: «موسى أذن أن يكتب كتاب طلاق, فتطلق».","10:5":"فأجاب يسوع وقال لهم: «من أجل قساوة قلوبكم كتب لكم هذه الوصية","10:6":"ولكن من بدء الخليقة, ذكرا وأنثى خلقهما الله.","10:7":"من أجل هذا يترك الرجل أباه وأمه ويلتصق بامرأته","10:8":"ويكون الاثنان جسدا واحدا. إذا ليسا بعد اثنين بل جسد واحد.","10:9":"فالذي جمعه الله لا يفرقه إنسان».","10:10":"ثم في البيت سأله تلاميذه أيضا عن ذلك","10:11":"فقال لهم: «من طلق امرأته وتزوج بأخرى يزني عليها.","10:12":"وإن طلقت امرأة زوجها وتزوجت بآخر تزني».","10:13":"وقدموا إليه أولادا لكي يلمسهم. وأما التلاميذ فانتهروا الذين قدموهم.","10:14":"فلما رأى يسوع ذلك اغتاظ وقال لهم: «دعوا الأولاد يأتون إلي ولا تمنعوهم, لأن لمثل هؤلاء ملكوت الله.","10:15":"الحق أقول لكم: من لا يقبل ملكوت الله مثل ولد فلن يدخله».","10:16":"فاحتضنهم ووضع يديه عليهم وباركهم.","10:17":"وفيما هو خارج إلى الطريق, ركض واحد وجثا له وسأله: «أيها المعلم الصالح, ماذا أعمل لأرث الحياة الأبدية؟»","10:18":"فقال له يسوع: «لماذا تدعوني صالحا؟ ليس أحد صالحا إلا واحد وهو الله.","10:19":"أنت تعرف الوصايا: لا تزن. لا تقتل. لا تسرق. لا تشهد بالزور. لا تسلب. أكرم أباك وأمك».","10:20":"فأجاب وقال له: «يا معلم, هذه كلها حفظتها منذ حداثتي».","10:21":"فنظر إليه يسوع وأحبه, وقال له: «يعوزك شيء واحد. اذهب بع كل ما لك وأعط الفقراء, فيكون لك كنز في السماء, وتعال اتبعني حاملا الصليب».","10:22":"فاغتم على القول ومضى حزينا, لأنه كان ذا أموال كثيرة.","10:23":"فنظر يسوع حوله وقال لتلاميذه: «ما أعسر دخول ذوي الأموال إلى ملكوت الله!»","10:24":"فتحير التلاميذ من كلامه. فأجاب يسوع أيضا وقال لهم: «يا بني, ما أعسر دخول المتكلين على الأموال إلى ملكوت الله!","10:25":"مرور جمل من ثقب إبرة أيسر من أن يدخل غني إلى ملكوت الله!»","10:26":"فبهتوا إلى الغاية قائلين بعضهم لبعض: «فمن يستطيع أن يخلص؟»","10:27":"فنظر إليهم يسوع وقال: «عند الناس غير مستطاع, ولكن ليس عند الله, لأن كل شيء مستطاع عند الله».","10:28":"وابتدأ بطرس يقول له: «ها نحن قد تركنا كل شيء وتبعناك».","10:29":"فأجاب يسوع وقال: «الحق أقول لكم ليس أحد ترك بيتا أو إخوة أو أخوات أو أبا أو أما أو امرأة أو أولادا أو حقولا, لأجلي ولأجل الإنجيل","10:30":"إلا ويأخذ مئة ضعف الآن في هذا الزمان, بيوتا وإخوة وأخوات وأمهات وأولادا وحقولا, مع اضطهادات, وفي الدهر الآتي الحياة الأبدية.","10:31":"ولكن كثيرون أولون يكونون آخرين, والآخرون أولين».","10:32":"وكانوا في الطريق صاعدين إلى أورشليم ويتقدمهم يسوع, وكانوا يتحيرون. وفيما هم يتبعون كانوا يخافون. فأخذ الاثني عشر أيضا وابتدأ يقول لهم عما سيحدث له:","10:33":"«ها نحن صاعدون إلى أورشليم, وابن الإنسان يسلم إلى رؤساء الكهنة والكتبة, فيحكمون عليه بالموت, ويسلمونه إلى الأمم","10:34":"فيهزأون به ويجلدونه ويتفلون عليه ويقتلونه, وفي اليوم الثالث يقوم».","10:35":"وتقدم إليه يعقوب ويوحنا ابنا زبدي قائلين: «يا معلم, نريد أن تفعل لنا كل ما طلبنا».","10:36":"فقال لهما: «ماذا تريدان أن أفعل لكما؟»","10:37":"فقالا له: «أعطنا أن نجلس واحد عن يمينك والآخر عن يسارك في مجدك».","10:38":"فقال لهما يسوع: «لستما تعلمان ما تطلبان. أتستطيعان أن تشربا الكأس التي أشربها أنا, وأن تصطبغا بالصبغة التي أصطبغ بها أنا؟»","10:39":"فقالا له: «نستطيع». فقال لهما يسوع: «أما الكأس التي أشربها أنا فتشربانها, وبالصبغة التي أصطبغ بها أنا تصطبغان.","10:40":"وأما الجلوس عن يميني وعن يساري فليس لي أن أعطيه إلا للذين أعد لهم».","10:41":"ولما سمع العشرة ابتدأوا يغتاظون من أجل يعقوب ويوحنا.","10:42":"فدعاهم يسوع وقال لهم: «أنتم تعلمون أن الذين يحسبون رؤساء الأمم يسودونهم, وأن عظماءهم يتسلطون عليهم.","10:43":"فلا يكون هكذا فيكم. بل من أراد أن يصير فيكم عظيما, يكون لكم خادما","10:44":"ومن أراد أن يصير فيكم أولا, يكون للجميع عبدا.","10:45":"لأن ابن الإنسان أيضا لم يأت ليخدم بل ليخدم وليبذل نفسه فدية عن كثيرين».","10:46":"وجاءوا إلى أريحا. وفيما هو خارج من أريحا مع تلاميذه وجمع غفير, كان بارتيماوس الأعمى ابن تيماوس جالسا على الطريق يستعطي.","10:47":"فلما سمع أنه يسوع الناصري, ابتدأ يصرخ ويقول: «يا يسوع ابن داود, ارحمني!»","10:48":"فانتهره كثيرون ليسكت, فصرخ أكثر كثيرا: «يا ابن داود, ارحمني».","10:49":"فوقف يسوع وأمر أن ينادى. فنادوا الأعمى قائلين له: «ثق. قم. هوذا يناديك».","10:50":"فطرح رداءه وقام وجاء إلى يسوع.","10:51":"فأجاب يسوع وقال له: «ماذا تريد أن أفعل بك؟» فقال له الأعمى: «يا سيدي, أن أبصر».","10:52":"فقال له يسوع: «اذهب. إيمانك قد شفاك». فللوقت أبصر, وتبع يسوع في الطريق.","11:1":"ولما قربوا من أورشليم إلى بيت فاجي وبيت عنيا, عند جبل الزيتون, أرسل اثنين من تلاميذه","11:2":"وقال لهما: «اذهبا إلى القرية التي أمامكما, فللوقت وأنتما داخلان إليها تجدان جحشا مربوطا لم يجلس عليه أحد من الناس. فحلاه وأتيا به.","11:3":"وإن قال لكما أحد: لماذا تفعلان هذا؟ فقولا: الرب محتاج إليه. فللوقت يرسله إلى هنا».","11:4":"فمضيا ووجدا الجحش مربوطا عند الباب خارجا على الطريق, فحلاه.","11:5":"فقال لهما قوم من القيام هناك: «ماذا تفعلان, تحلان الجحش؟»","11:6":"فقالا لهم كما أوصى يسوع. فتركوهما.","11:7":"فأتيا بالجحش إلى يسوع, وألقيا عليه ثيابهما فجلس عليه.","11:8":"وكثيرون فرشوا ثيابهم في الطريق وآخرون قطعوا أغصانا من الشجر وفرشوها في الطريق.","11:9":"والذين تقدموا, والذين تبعوا كانوا يصرخون قائلين: «أوصنا! مبارك الآتي باسم الرب!","11:10":"مباركة مملكة أبينا داود الآتية باسم الرب! أوصنا في الأعالي!».","11:11":"فدخل يسوع أورشليم والهيكل, ولما نظر حوله إلى كل شيء إذ كان الوقت قد أمسى, خرج إلى بيت عنيا مع الاثني عشر.","11:12":"وفي الغد لما خرجوا من بيت عنيا جاع","11:13":"فنظر شجرة تين من بعيد عليها ورق, وجاء لعله يجد فيها شيئا. فلما جاء إليها لم يجد شيئا إلا ورقا, لأنه لم يكن وقت التين.","11:14":"فأجاب يسوع وقال لها: «لا يأكل أحد منك ثمرا بعد إلى الأبد». وكان تلاميذه يسمعون.","11:15":"وجاءوا إلى أورشليم. ولما دخل يسوع الهيكل ابتدأ يخرج الذين كانوا يبيعون ويشترون في الهيكل, وقلب موائد الصيارفة وكراسي باعة الحمام.","11:16":"ولم يدع أحدا يجتاز الهيكل بمتاع.","11:17":"وكان يعلم قائلا لهم: «أليس مكتوبا: بيتي بيت صلاة يدعى لجميع الأمم؟ وأنتم جعلتموه مغارة لصوص».","11:18":"وسمع الكتبة ورؤساء الكهنة فطلبوا كيف يهلكونه, لأنهم خافوه, إذ بهت الجمع كله من تعليمه.","11:19":"ولما صار المساء, خرج إلى خارج المدينة.","11:20":"وفي الصباح إذ كانوا مجتازين رأوا التينة قد يبست من الأصول","11:21":"فتذكر بطرس وقال له: «يا سيدي, انظر التينة التي لعنتها قد يبست!»","11:22":"فأجاب يسوع وقال لهم: «ليكن لكم إيمان بالله.","11:23":"لأني الحق أقول لكم: إن من قال لهذا الجبل انتقل وانطرح في البحر ولا يشك في قلبه, بل يؤمن أن ما يقوله يكون, فمهما قال يكون له.","11:24":"لذلك أقول لكم: كل ما تطلبونه حينما تصلون, فآمنوا أن تنالوه, فيكون لكم.","11:25":"ومتى وقفتم تصلون, فاغفروا إن كان لكم على أحد شيء, لكي يغفر لكم أيضا أبوكم الذي في السماوات زلاتكم.","11:26":"وإن لم تغفروا أنتم لا يغفر أبوكم الذي في السماوات أيضا زلاتكم».","11:27":"وجاءوا أيضا إلى أورشليم. وفيما هو يمشي في الهيكل, أقبل إليه رؤساء الكهنة والكتبة والشيوخ","11:28":"وقالوا له: «بأي سلطان تفعل هذا ومن أعطاك هذا السلطان حتى تفعل هذا؟»","11:29":"فأجاب يسوع وقال لهم: «وأنا أيضا أسألكم كلمة واحدة. أجيبوني, فأقول لكم بأي سلطان أفعل هذا:","11:30":"معمودية يوحنا: من السماء كانت أم من الناس؟ أجيبوني».","11:31":"ففكروا في أنفسهم قائلين: «إن قلنا من السماء, يقول: فلماذا لم تؤمنوا به؟","11:32":"وإن قلنا من الناس». فخافوا الشعب. لأن يوحنا كان عند الجميع أنه بالحقيقة نبي.","11:33":"فأجابوا وقالوا ليسوع: «لا نعلم». فأجاب يسوع وقال لهم: «ولا أنا أقول لكم بأي سلطان أفعل هذا».","12:1":"وابتدأ يقول لهم بأمثال: «إنسان غرس كرما وأحاطه بسياج, وحفر حوض معصرة, وبنى برجا, وسلمه إلى كرامين وسافر.","12:2":"ثم أرسل إلى الكرامين في الوقت عبدا ليأخذ من الكرامين من ثمر الكرم","12:3":"فأخذوه وجلدوه وأرسلوه فارغا.","12:4":"ثم أرسل إليهم أيضا عبدا آخر, فرجموه وشجوه وأرسلوه مهانا.","12:5":"ثم أرسل أيضا آخر, فقتلوه. ثم آخرين كثيرين, فجلدوا منهم بعضا وقتلوا بعضا.","12:6":"فإذ كان له أيضا ابن واحد حبيب إليه أرسله أيضا إليهم أخيرا, قائلا: إنهم يهابون ابني.","12:7":"ولكن أولئك الكرامين قالوا فيما بينهم: هذا هو الوارث! هلموا نقتله فيكون لنا الميراث!","12:8":"فأخذوه وقتلوه وأخرجوه خارج الكرم.","12:9":"فماذا يفعل صاحب الكرم؟ يأتي ويهلك الكرامين, ويعطي الكرم إلى آخرين.","12:10":"أما قرأتم هذا المكتوب: الحجر الذي رفضه البناؤون, هو قد صار رأس الزاوية","12:11":"من قبل الرب كان هذا, وهو عجيب في أعيننا!»","12:12":"فطلبوا أن يمسكوه, ولكنهم خافوا من الجمع, لأنهم عرفوا أنه قال المثل عليهم. فتركوه ومضوا.","12:13":"ثم أرسلوا إليه قوما من الفريسيين والهيرودسيين لكي يصطادوه بكلمة.","12:14":"فلما جاءوا قالوا له: «يا معلم, نعلم أنك صادق ولا تبالي بأحد, لأنك لا تنظر إلى وجوه الناس, بل بالحق تعلم طريق الله. أيجوز أن تعطى جزية لقيصر أم لا؟ نعطي أم لا نعطي؟»","12:15":"فعلم رياءهم, وقال لهم: «لماذا تجربونني؟ ايتوني بدينار لأنظره».","12:16":"فأتوا به. فقال لهم: «لمن هذه الصورة والكتابة؟» فقالوا له: «لقيصر».","12:17":"فأجاب يسوع وقال لهم: «أعطوا ما لقيصر لقيصر وما لله لله». فتعجبوا منه.","12:18":"وجاء إليه قوم من الصدوقيين, الذين يقولون ليس قيامة, وسألوه قائلين:","12:19":"«يا معلم, كتب لنا موسى: إن مات لأحد أخ, وترك امرأة ولم يخلف أولادا, أن يأخذ أخوه امرأته, ويقيم نسلا لأخيه.","12:20":"فكان سبعة إخوة. أخذ الأول امرأة ومات, ولم يترك نسلا.","12:21":"فأخذها الثاني ومات, ولم يترك هو أيضا نسلا. وهكذا الثالث.","12:22":"فأخذها السبعة, ولم يتركوا نسلا. وآخر الكل ماتت المرأة أيضا.","12:23":"ففي القيامة, متى قاموا, لمن منهم تكون زوجة؟ لأنها كانت زوجة للسبعة».","12:24":"فأجاب يسوع وقال لهم: «أليس لهذا تضلون, إذ لا تعرفون الكتب ولا قوة الله؟","12:25":"لأنهم متى قاموا من الأموات لا يزوجون ولا يزوجون, بل يكونون كملائكة في السماوات.","12:26":"وأما من جهة الأموات إنهم يقومون: أفما قرأتم في كتاب موسى, في أمر العليقة, كيف كلمه الله قائلا: أنا إله إبراهيم وإله إسحاق وإله يعقوب؟","12:27":"ليس هو إله أموات بل إله أحياء. فأنتم إذا تضلون كثيرا».","12:28":"فجاء واحد من الكتبة وسمعهم يتحاورون, فلما رأى أنه أجابهم حسنا, سأله: «أية وصية هي أول الكل؟»","12:29":"فأجابه يسوع: «إن أول كل الوصايا هي: اسمع يا إسرائيل. الرب إلهنا رب واحد.","12:30":"وتحب الرب إلهك من كل قلبك, ومن كل نفسك, ومن كل فكرك, ومن كل قدرتك. هذه هي الوصية الأولى.","12:31":"وثانية مثلها هي: تحب قريبك كنفسك. ليس وصية أخرى أعظم من هاتين».","12:32":"فقال له الكاتب: «جيدا يا معلم. بالحق قلت, لأنه الله واحد وليس آخر سواه.","12:33":"ومحبته من كل القلب, ومن كل الفهم, ومن كل النفس, ومن كل القدرة, ومحبة القريب كالنفس, هي أفضل من جميع المحرقات والذبائح».","12:34":"فلما رآه يسوع أنه أجاب بعقل, قال له: «لست بعيدا عن ملكوت الله». ولم يجسر أحد بعد ذلك أن يسأله!","12:35":"ثم أجاب يسوع وقال وهو يعلم في الهيكل: «كيف يقول الكتبة إن المسيح ابن داود؟","12:36":"لأن داود نفسه قال بالروح القدس: قال الرب لربي: اجلس عن يميني, حتى أضع أعداءك موطئا لقدميك.","12:37":"فداود نفسه يدعوه ربا. فمن أين هو ابنه؟» وكان الجمع الكثير يسمعه بسرور.","12:38":"وقال لهم في تعليمه: «تحرزوا من الكتبة, الذين يرغبون المشي بالطيالسة, والتحيات في الأسواق","12:39":"والمجالس الأولى في المجامع, والمتكآت الأولى في الولائم.","12:40":"الذين يأكلون بيوت الأرامل, ولعلة يطيلون الصلوات. هؤلاء يأخذون دينونة أعظم».","12:41":"وجلس يسوع تجاه الخزانة, ونظر كيف يلقي الجمع نحاسا في الخزانة. وكان أغنياء كثيرون يلقون كثيرا.","12:42":"فجاءت أرملة فقيرة وألقت فلسين, قيمتهما ربع.","12:43":"فدعا تلاميذه وقال لهم: «الحق أقول لكم: إن هذه الأرملة الفقيرة قد ألقت أكثر من جميع الذين ألقوا في الخزانة","12:44":"لأن الجميع من فضلتهم ألقوا. وأما هذه فمن إعوازها ألقت كل ما عندها, كل معيشتها».","13:1":"وفيما هو خارج من الهيكل, قال له واحد من تلاميذه: «يا معلم انظر ما هذه الحجارة وهذه الأبنية؟»","13:2":"فأجاب يسوع وقال له: «أتنظر هذه الأبنية العظيمة؟ لا يترك حجر على حجر لا ينقض».","13:3":"وفيما هو جالس على جبل الزيتون, تجاه الهيكل, سأله بطرس ويعقوب ويوحنا وأندراوس على انفراد:","13:4":"«قل لنا متى يكون هذا وما هي العلامة عندما يتم جميع هذا؟»","13:5":"فأجابهم يسوع وابتدأ يقول: «انظروا! لا يضلكم أحد.","13:6":"فإن كثيرين سيأتون باسمي قائلين: إني أنا هو. ويضلون كثيرين.","13:7":"فإذا سمعتم بحروب وبأخبار حروب فلا ترتاعوا, لأنها لا بد أن تكون, ولكن ليس المنتهى بعد.","13:8":"لأنه تقوم أمة على أمة, ومملكة على مملكة, وتكون زلازل في أماكن, وتكون مجاعات واضطرابات. هذه مبتدأ الأوجاع.","13:9":"فانظروا إلى نفوسكم. لأنهم سيسلمونكم إلى مجالس, وتجلدون في مجامع, وتوقفون أمام ولاة وملوك, من أجلي, شهادة لهم.","13:10":"وينبغي أن يكرز أولا بالإنجيل في جميع الأمم.","13:11":"فمتى ساقوكم ليسلموكم, فلا تعتنوا من قبل بما تتكلمون ولا تهتموا, بل مهما أعطيتم في تلك الساعة فبذلك تكلموا لأن لستم أنتم المتكلمين بل الروح القدس.","13:12":"وسيسلم الأخ أخاه إلى الموت, والأب ولده, ويقوم الأولاد على والديهم ويقتلونهم.","13:13":"وتكونون مبغضين من الجميع من أجل اسمي. ولكن الذي يصبر إلى المنتهى فهذا يخلص.","13:14":"فمتى نظرتم «رجسة الخراب» التي قال عنها دانيآل النبي, قائمة حيث لا ينبغي - ليفهم القارئ - فحينئذ ليهرب الذين في اليهودية إلى الجبال","13:15":"والذي على السطح فلا ينزل إلى البيت ولا يدخل ليأخذ من بيته شيئا","13:16":"والذي في الحقل فلا يرجع إلى الوراء ليأخذ ثوبه.","13:17":"وويل للحبالى والمرضعات في تلك الأيام.","13:18":"وصلوا لكي لا يكون هربكم في شتاء.","13:19":"لأنه يكون في تلك الأيام ضيق لم يكن مثله منذ ابتداء الخليقة التي خلقها الله إلى الآن, ولن يكون.","13:20":"ولو لم يقصر الرب تلك الأيام, لم يخلص جسد. ولكن لأجل المختارين الذين اختارهم, قصر الأيام.","13:21":"حينئذ إن قال لكم أحد: هوذا المسيح هنا أو هوذا هناك فلا تصدقوا.","13:22":"لأنه سيقوم مسحاء كذبة وأنبياء كذبة, ويعطون آيات وعجائب, لكي يضلوا - لو أمكن - المختارين أيضا.","13:23":"فانظروا أنتم. ها أنا قد سبقت وأخبرتكم بكل شيء.","13:24":"«وأما في تلك الأيام بعد ذلك الضيق, فالشمس تظلم, والقمر لا يعطي ضوءه","13:25":"ونجوم السماء تتساقط, والقوات التي في السماوات تتزعزع.","13:26":"وحينئذ يبصرون ابن الإنسان آتيا في سحاب بقوة كثيرة ومجد","13:27":"فيرسل حينئذ ملائكته ويجمع مختاريه من الأربع الرياح, من أقصاء الأرض إلى أقصاء السماء.","13:28":"فمن شجرة التين تعلموا المثل: متى صار غصنها رخصا وأخرجت أوراقا, تعلمون أن الصيف قريب.","13:29":"هكذا أنتم أيضا, متى رأيتم هذه الأشياء صائرة, فاعلموا أنه قريب على الأبواب.","13:30":"الحق أقول لكم: لا يمضي هذا الجيل حتى يكون هذا كله.","13:31":"السماء والأرض تزولان, ولكن كلامي لا يزول.","13:32":"وأما ذلك اليوم وتلك الساعة فلا يعلم بهما أحد, ولا الملائكة الذين في السماء, ولا الابن, إلا الآب.","13:33":"انظروا! اسهروا وصلوا, لأنكم لا تعلمون متى يكون الوقت.","13:34":"كأنما إنسان مسافر ترك بيته, وأعطى عبيده السلطان, ولكل واحد عمله, وأوصى البواب أن يسهر.","13:35":"اسهروا إذا, لأنكم لا تعلمون متى يأتي رب البيت, أمساء, أم نصف الليل, أم صياح الديك, أم صباحا.","13:36":"لئلا يأتي بغتة فيجدكم نياما!","13:37":"وما أقوله لكم أقوله للجميع: اسهروا».","14:1":"وكان الفصح وأيام الفطير بعد يومين. وكان رؤساء الكهنة والكتبة يطلبون كيف يمسكونه بمكر ويقتلونه","14:2":"ولكنهم قالوا: «ليس في العيد, لئلا يكون شغب في الشعب».","14:3":"وفيما هو في بيت عنيا في بيت سمعان الأبرص, وهو متكئ, جاءت امرأة معها قارورة طيب ناردين خالص كثير الثمن. فكسرت القارورة وسكبته على رأسه.","14:4":"وكان قوم مغتاظين في أنفسهم, فقالوا: «لماذا كان تلف الطيب هذا؟","14:5":"لأنه كان يمكن أن يباع هذا بأكثر من ثلاثمئة دينار ويعطى للفقراء». وكانوا يؤنبونها.","14:6":"أما يسوع فقال: «اتركوها! لماذا تزعجونها؟ قد عملت بي عملا حسنا.","14:7":"لأن الفقراء معكم في كل حين, ومتى أردتم تقدرون أن تعملوا بهم خيرا. وأما أنا فلست معكم في كل حين.","14:8":"عملت ما عندها. قد سبقت ودهنت بالطيب جسدي للتكفين.","14:9":"الحق أقول لكم: حيثما يكرز بهذا الإنجيل في كل العالم, يخبر أيضا بما فعلته هذه, تذكارا لها».","14:10":"ثم إن يهوذا الإسخريوطي, واحدا من الاثني عشر, مضى إلى رؤساء الكهنة ليسلمه إليهم.","14:11":"ولما سمعوا فرحوا, ووعدوه أن يعطوه فضة. وكان يطلب كيف يسلمه في فرصة موافقة.","14:12":"وفي اليوم الأول من الفطير. حين كانوا يذبحون الفصح, قال له تلاميذه: «أين تريد أن نمضي ونعد لتأكل الفصح؟»","14:13":"فأرسل اثنين من تلاميذه وقال لهما: «اذهبا إلى المدينة, فيلاقيكما إنسان حامل جرة ماء. اتبعاه.","14:14":"وحيثما يدخل فقولا لرب البيت: إن المعلم يقول: أين المنزل حيث آكل الفصح مع تلاميذي؟","14:15":"فهو يريكما علية كبيرة مفروشة معدة. هناك أعدا لنا».","14:16":"فخرج تلميذاه وأتيا إلى المدينة, ووجدا كما قال لهما. فأعدا الفصح.","14:17":"ولما كان المساء جاء مع الاثني عشر.","14:18":"وفيما هم متكئون يأكلون, قال يسوع: «الحق أقول لكم: إن واحدا منكم يسلمني. الآكل معي!»","14:19":"فابتدأوا يحزنون, ويقولون له واحدا فواحدا: «هل أنا؟» وآخر: «هل أنا؟»","14:20":"فأجاب وقال لهم: «هو واحد من الاثني عشر, الذي يغمس معي في الصحفة.","14:21":"إن ابن الإنسان ماض كما هو مكتوب عنه, ولكن ويل لذلك الرجل الذي به يسلم ابن الإنسان. كان خيرا لذلك الرجل لو لم يولد!».","14:22":"وفيما هم يأكلون, أخذ يسوع خبزا وبارك وكسر, وأعطاهم وقال: «خذوا كلوا, هذا هو جسدي».","14:23":"ثم أخذ الكأس وشكر وأعطاهم, فشربوا منها كلهم.","14:24":"وقال لهم: «هذا هو دمي الذي للعهد الجديد, الذي يسفك من أجل كثيرين.","14:25":"الحق أقول لكم: إني لا أشرب بعد من نتاج الكرمة إلى ذلك اليوم حينما أشربه جديدا في ملكوت الله».","14:26":"ثم سبحوا وخرجوا إلى جبل الزيتون.","14:27":"وقال لهم يسوع: «إن كلكم تشكون في في هذه الليلة, لأنه مكتوب: أني أضرب الراعي فتتبدد الخراف.","14:28":"ولكن بعد قيامي أسبقكم إلى الجليل».","14:29":"فقال له بطرس: «وإن شك الجميع فأنا لا أشك!»","14:30":"فقال له يسوع: «الحق أقول لك إنك اليوم في هذه الليلة, قبل أن يصيح الديك مرتين, تنكرني ثلاث مرات».","14:31":"فقال بأكثر تشديد: «ولو اضطررت أن أموت معك لا أنكرك». وهكذا قال أيضا الجميع.","14:32":"وجاءوا إلى ضيعة اسمها جثسيماني, فقال لتلاميذه: «اجلسوا ههنا حتى أصلي».","14:33":"ثم أخذ معه بطرس ويعقوب ويوحنا, وابتدأ يدهش ويكتئب.","14:34":"فقال لهم: «نفسي حزينة جدا حتى الموت! امكثوا هنا واسهروا».","14:35":"ثم تقدم قليلا وخر على الأرض, وكان يصلي لكي تعبر عنه الساعة إن أمكن.","14:36":"وقال: «يا أبا الآب, كل شيء مستطاع لك, فأجز عني هذه الكأس. ولكن ليكن لا ما أريد أنا, بل ما تريد أنت».","14:37":"ثم جاء ووجدهم نياما, فقال لبطرس: «يا سمعان, أنت نائم! أما قدرت أن تسهر ساعة واحدة؟","14:38":"اسهروا وصلوا لئلا تدخلوا في تجربة. أما الروح فنشيط, وأما الجسد فضعيف».","14:39":"ومضى أيضا وصلى قائلا ذلك الكلام بعينه.","14:40":"ثم رجع ووجدهم أيضا نياما, إذ كانت أعينهم ثقيلة, فلم يعلموا بماذا يجيبونه.","14:41":"ثم جاء ثالثة وقال لهم: «ناموا الآن واستريحوا! يكفي! قد أتت الساعة! هوذا ابن الإنسان يسلم إلى أيدي الخطاة.","14:42":"قوموا لنذهب. هوذا الذي يسلمني قد اقترب».","14:43":"وللوقت فيما هو يتكلم أقبل يهوذا, واحد من الاثني عشر, ومعه جمع كثير بسيوف وعصي من عند رؤساء الكهنة والكتبة والشيوخ.","14:44":"وكان مسلمه قد أعطاهم علامة قائلا: «الذي أقبله هو هو. أمسكوه, وامضوا به بحرص».","14:45":"فجاء للوقت وتقدم إليه قائلا: «يا سيدي يا سيدي!» وقبله.","14:46":"فألقوا أيديهم عليه وأمسكوه.","14:47":"فاستل واحد من الحاضرين السيف, وضرب عبد رئيس الكهنة فقطع أذنه.","14:48":"فأجاب يسوع وقال لهم: «كأنه على لص خرجتم بسيوف وعصي لتأخذوني!","14:49":"كل يوم كنت معكم في الهيكل أعلم ولم تمسكوني! ولكن لكي تكمل الكتب».","14:50":"فتركه الجميع وهربوا.","14:51":"وتبعه شاب لابسا إزارا على عريه, فأمسكه الشبان","14:52":"فترك الإزار وهرب منهم عريانا.","14:53":"فمضوا بيسوع إلى رئيس الكهنة, فاجتمع معه جميع رؤساء الكهنة والشيوخ والكتبة.","14:54":"وكان بطرس قد تبعه من بعيد إلى داخل دار رئيس الكهنة, وكان جالسا بين الخدام يستدفئ عند النار.","14:55":"وكان رؤساء الكهنة والمجمع كله يطلبون شهادة على يسوع ليقتلوه, فلم يجدوا","14:56":"لأن كثيرين شهدوا عليه زورا, ولم تتفق شهاداتهم.","14:57":"ثم قام قوم وشهدوا عليه زورا قائلين:","14:58":"«نحن سمعناه يقول: إني أنقض هذا الهيكل المصنوع بالأيادي, وفي ثلاثة أيام أبني آخر غير مصنوع بأياد».","14:59":"ولا بهذا كانت شهادتهم تتفق.","14:60":"فقام رئيس الكهنة في الوسط وسأل يسوع قائلا: «أما تجيب بشيء؟ ماذا يشهد به هؤلاء عليك؟»","14:61":"أما هو فكان ساكتا ولم يجب بشيء. فسأله رئيس الكهنة أيضا وقال له: «أأنت المسيح ابن المبارك؟»","14:62":"فقال يسوع: «أنا هو. وسوف تبصرون ابن الإنسان جالسا عن يمين القوة, وآتيا في سحاب السماء».","14:63":"فمزق رئيس الكهنة ثيابه وقال: «ما حاجتنا بعد إلى شهود؟","14:64":"قد سمعتم التجاديف! ما رأيكم؟» فالجميع حكموا عليه أنه مستوجب الموت.","14:65":"فابتدأ قوم يبصقون عليه, ويغطون وجهه ويلكمونه ويقولون له: «تنبأ». وكان الخدام يلطمونه.","14:66":"وبينما كان بطرس في الدار أسفل جاءت إحدى جواري رئيس الكهنة.","14:67":"فلما رأت بطرس يستدفئ, نظرت إليه وقالت: «وأنت كنت مع يسوع الناصري!»","14:68":"فأنكر قائلا: «لست أدري ولا أفهم ما تقولين!» وخرج خارجا إلى الدهليز, فصاح الديك.","14:69":"فرأته الجارية أيضا وابتدأت تقول للحاضرين: «إن هذا منهم!»","14:70":"فأنكر أيضا. وبعد قليل أيضا قال الحاضرون لبطرس: «حقا أنت منهم, لأنك جليلي أيضا ولغتك تشبه لغتهم».","14:71":"فابتدأ يلعن ويحلف: «إني لا أعرف هذا الرجل الذي تقولون عنه!»","14:72":"وصاح الديك ثانية, فتذكر بطرس القول الذي قاله له يسوع: «إنك قبل أن يصيح الديك مرتين, تنكرني ثلاث مرات». فلما تفكر به بكى.","15:1":"وللوقت في الصباح تشاور رؤساء الكهنة والشيوخ والكتبة والمجمع كله, فأوثقوا يسوع ومضوا به وأسلموه إلى بيلاطس.","15:2":"فسأله بيلاطس: «أأنت ملك اليهود؟» فأجاب وقال له: «أنت تقول».","15:3":"وكان رؤساء الكهنة يشتكون عليه كثيرا.","15:4":"فسأله بيلاطس أيضا قائلا: «أما تجيب بشيء؟ انظر كم يشهدون عليك!»","15:5":"فلم يجب يسوع أيضا بشيء حتى تعجب بيلاطس.","15:6":"وكان يطلق لهم في كل عيد أسيرا واحدا, من طلبوه.","15:7":"وكان المسمى باراباس موثقا مع رفقائه في الفتنة, الذين في الفتنة فعلوا قتلا.","15:8":"فصرخ الجمع وابتدأوا يطلبون أن يفعل كما كان دائما يفعل لهم.","15:9":"فأجابهم بيلاطس: «أتريدون أن أطلق لكم ملك اليهود؟».","15:10":"لأنه عرف أن رؤساء الكهنة كانوا قد أسلموه حسدا.","15:11":"فهيج رؤساء الكهنة الجمع لكي يطلق لهم بالحري باراباس.","15:12":"فأجاب بيلاطس أيضا وقال لهم: «فماذا تريدون أن أفعل بالذي تدعونه ملك اليهود؟»","15:13":"فصرخوا أيضا: «اصلبه!»","15:14":"فقال لهم بيلاطس: «وأي شر عمل؟» فازدادوا جدا صراخا: «اصلبه!»","15:15":"فبيلاطس إذ كان يريد أن يعمل للجمع ما يرضيهم, أطلق لهم باراباس, وأسلم يسوع, بعدما جلده, ليصلب.","15:16":"فمضى به العسكر إلى داخل الدار, التي هي دار الولاية, وجمعوا كل الكتيبة.","15:17":"وألبسوه أرجوانا, وضفروا إكليلا من شوك ووضعوه عليه","15:18":"وابتدأوا يسلمون عليه قائلين: «السلام يا ملك اليهود!»","15:19":"وكانوا يضربونه على رأسه بقصبة, ويبصقون عليه, ثم يسجدون له جاثين على ركبهم.","15:20":"وبعدما استهزأوا به, نزعوا عنه الأرجوان وألبسوه ثيابه, ثم خرجوا به ليصلبوه.","15:21":"فسخروا رجلا مجتازا كان آتيا من الحقل, وهو سمعان القيرواني أبو ألكسندرس وروفس, ليحمل صليبه.","15:22":"وجاءوا به إلى موضع «جلجثة» الذي تفسيره موضع «جمجمة».","15:23":"وأعطوه خمرا ممزوجة بمر ليشرب, فلم يقبل.","15:24":"ولما صلبوه اقتسموا ثيابه مقترعين عليها: ماذا يأخذ كل واحد؟","15:25":"وكانت الساعة الثالثة فصلبوه.","15:26":"وكان عنوان علته مكتوبا «ملك اليهود».","15:27":"وصلبوا معه لصين, واحدا عن يمينه وآخر عن يساره.","15:28":"فتم الكتاب القائل: «وأحصي مع أثمة».","15:29":"وكان المجتازون يجدفون عليه, وهم يهزون رؤوسهم قائلين: «آه يا ناقض الهيكل وبانيه في ثلاثة أيام!","15:30":"خلص نفسك وانزل عن الصليب!»","15:31":"وكذلك رؤساء الكهنة وهم مستهزئون فيما بينهم مع الكتبة, قالوا: «خلص آخرين وأما نفسه فما يقدر أن يخلصها.","15:32":"لينزل الآن المسيح ملك إسرائيل عن الصليب, لنرى ونؤمن». واللذان صلبا معه كانا يعيرانه.","15:33":"ولما كانت الساعة السادسة, كانت ظلمة على الأرض كلها إلى الساعة التاسعة.","15:34":"وفي الساعة التاسعة صرخ يسوع بصوت عظيم قائلا: «إلوي, إلوي, لما شبقتني؟» (الذي تفسيره: إلهي, إلهي, لماذا تركتني؟)","15:35":"فقال قوم من الحاضرين لما سمعوا: «هوذا ينادي إيليا».","15:36":"فركض واحد وملأ إسفنجة خلا وجعلها على قصبة وسقاه قائلا: «اتركوا. لنر هل يأتي إيليا لينزله!»","15:37":"فصرخ يسوع بصوت عظيم وأسلم الروح.","15:38":"وانشق حجاب الهيكل إلى اثنين, من فوق إلى أسفل.","15:39":"ولما رأى قائد المئة الواقف مقابله أنه صرخ هكذا وأسلم الروح, قال: «حقا كان هذا الإنسان ابن الله!»","15:40":"وكانت أيضا نساء ينظرن من بعيد, بينهن مريم المجدلية, ومريم أم يعقوب الصغير ويوسي, وسالومة","15:41":"اللواتي أيضا تبعنه وخدمنه حين كان في الجليل. وأخر كثيرات اللواتي صعدن معه إلى أورشليم.","15:42":"ولما كان المساء, إذ كان الاستعداد, - أي ما قبل السبت -","15:43":"جاء يوسف الذي من الرامة, مشير شريف, وكان هو أيضا منتظرا ملكوت الله, فتجاسر ودخل إلى بيلاطس وطلب جسد يسوع.","15:44":"فتعجب بيلاطس أنه مات كذا سريعا. فدعا قائد المئة وسأله: «هل له زمان قد مات؟»","15:45":"ولما عرف من قائد المئة, وهب الجسد ليوسف.","15:46":"فاشترى كتانا, فأنزله وكفنه بالكتان, ووضعه في قبر كان منحوتا في صخرة, ودحرج حجرا على باب القبر.","15:47":"وكانت مريم المجدلية ومريم أم يوسي تنظران أين وضع.","16:1":"وبعدما مضى السبت, اشترت مريم المجدلية ومريم أم يعقوب وسالومة, حنوطا ليأتين ويدهنه.","16:2":"وباكرا جدا في أول الأسبوع أتين إلى القبر إذ طلعت الشمس.","16:3":"وكن يقلن فيما بينهن: «من يدحرج لنا الحجر عن باب القبر؟»","16:4":"فتطلعن ورأين أن الحجر قد دحرج! لأنه كان عظيما جدا.","16:5":"ولما دخلن القبر رأين شابا جالسا عن اليمين لابسا حلة بيضاء, فاندهشن.","16:6":"فقال لهن: «لا تندهشن! أنتن تطلبن يسوع الناصري المصلوب. قد قام! ليس هو ههنا. هوذا الموضع الذي وضعوه فيه.","16:7":"لكن اذهبن وقلن لتلاميذه ولبطرس إنه يسبقكم إلى الجليل. هناك ترونه كما قال لكم».","16:8":"فخرجن سريعا وهربن من القبر, لأن الرعدة والحيرة أخذتاهن. ولم يقلن لأحد شيئا لأنهن كن خائفات.","16:9":"وبعدما قام باكرا في أول الأسبوع ظهر أولا لمريم المجدلية, التي كان قد أخرج منها سبعة شياطين.","16:10":"فذهبت هذه وأخبرت الذين كانوا معه وهم ينوحون ويبكون.","16:11":"فلما سمع أولئك أنه حي, وقد نظرته, لم يصدقوا.","16:12":"وبعد ذلك ظهر بهيئة أخرى لاثنين منهم, وهما يمشيان منطلقين إلى البرية.","16:13":"وذهب هذان وأخبرا الباقين, فلم يصدقوا ولا هذين.","16:14":"أخيرا ظهر للأحد عشر وهم متكئون, ووبخ عدم إيمانهم وقساوة قلوبهم, لأنهم لم يصدقوا الذين نظروه قد قام.","16:15":"وقال لهم: «اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها.","16:16":"من آمن واعتمد خلص, ومن لم يؤمن يدن.","16:17":"وهذه الآيات تتبع المؤمنين: يخرجون الشياطين باسمي, ويتكلمون بألسنة جديدة.","16:18":"يحملون حيات, وإن شربوا شيئا مميتا لا يضرهم, ويضعون أيديهم على المرضى فيبرأون».","16:19":"ثم إن الرب بعدما كلمهم ارتفع إلى السماء, وجلس عن يمين الله.","16:20":"وأما هم فخرجوا وكرزوا في كل مكان, والرب يعمل معهم ويثبت الكلام بالآيات التابعة. آمين."};
